    time_min = '2026-01-06T00:00:00Z'
    time_max = '2026-01-10T00:00:00Z'
    events_result = service.events().list(calendarId='primary', timeMin=time_min, timeMax=time_max, singleEvents=True, orderBy='startTime').execute()
